from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult
from langchain_core.tools import tool
from deepagents import FilesystemPermission, create_deep_agent


class Guion(BaseChatModel):
    """Modelo falso: anota qué tools recibe y qué lee, y responde en orden."""
    nombre: str
    guion: list
    i: int = 0

    @property
    def _llm_type(self):
        return "guion"

    def bind_tools(self, tools, **kw):
        if self.i == 0:
            print(f"[{self.nombre} tools] {[t.name for t in tools]}")
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kw):
        if self.i == 0:
            print(f"[{self.nombre} system prompt] {messages[0].content!r}")
        else:
            print(f"[{self.nombre} lee] {messages[-1].content!r}")
        respuesta = self.guion[self.i]
        self.i += 1
        return ChatResult(generations=[ChatGeneration(message=respuesta)])


@tool
def internet_search(query: str) -> str:
    """Busca noticias en la web."""
    return f"resultados para {query}"


@tool
def markdown_to_html(markdown_text: str) -> str:
    """Convierte Markdown a HTML."""
    return "<html>...</html>"


# El sub intenta escribir FUERA de /research/.
modelo_sub = Guion(nombre="SUB", guion=[
    AIMessage(content="", tool_calls=[{
        "name": "write_file",
        "args": {"file_path": "/output/hack.html", "content": "x"}, "id": "w1"}]),
    AIMessage(content="## Rock\nsegmento"),
])

# El editor delega y luego intenta escribir DENTRO de /research/.
modelo_editor = Guion(nombre="EDITOR", guion=[
    AIMessage(content="", tool_calls=[{
        "name": "task",
        "args": {"subagent_type": "genre-researcher", "description": "Investiga Rock."},
        "id": "t1"}]),
    AIMessage(content="", tool_calls=[{
        "name": "write_file",
        "args": {"file_path": "/research/Rock/notas.md", "content": "x"}, "id": "w2"}]),
    AIMessage(content="fin"),
])

agent = create_deep_agent(
    model=modelo_editor,
    tools=[markdown_to_html],
    system_prompt="Eres el editor del newsletter.",
    subagents=[{
        "name": "genre-researcher",
        "description": "Investiga un género musical.",
        "system_prompt": "Eres periodista musical.",
        "tools": [internet_search],
        "model": modelo_sub,
        "permissions": [
            FilesystemPermission(operations=["read", "write"], paths=["/research/**"], mode="allow"),
            FilesystemPermission(operations=["write"], paths=["/**"], mode="deny"),
        ],
    }],
    permissions=[
        FilesystemPermission(operations=["write"], paths=["/research/**"], mode="deny"),
    ],
)

agent.invoke({"messages": [{"role": "user", "content": "Arma el newsletter."}]})
